import type { Metadata } from "next";
import { SITE_NAME } from "../../configurations/site";
import LegalHeader from "../../components/LegalHeader";
import credits from "../../data/photo-credits.json";

// Player photos from Wikimedia Commons are public domain or Creative Commons; the CC
// licenses require naming the author and license and linking the source, which this page
// does for every file. The list is generated by scripts/player-photos/build.mjs.
export const metadata: Metadata = {
  title: "Photo credits",
  description: `Credits for the player photos used in ${SITE_NAME} that come from Wikimedia Commons.`,
  alternates: { canonical: "/credits" },
  robots: { index: false },
};

interface Credit {
  player: string;
  file: string;
  artist: string;
  license: string;
  license_url: string;
}

const link = { color: "var(--brand)" };

export default function CreditsPage() {
  const rows = credits as Credit[];
  return (
    <>
      <LegalHeader />
      <main style={{ background: "var(--bg)", color: "var(--text)", minHeight: "100vh", padding: "2rem 1.25rem 5rem" }}>
        <article style={{ maxWidth: 820, margin: "0 auto", lineHeight: 1.7 }}>
          <h1 style={{ fontSize: "2.25rem", fontWeight: 800, margin: "0.5rem 0 0.25rem" }}>Photo credits</h1>
          <p style={{ color: "var(--muted)", marginBottom: "1.5rem" }}>
            Most player photos come from cdn.nba.com. For {rows.length} players without one there, we show a photo from{" "}
            <a href="https://commons.wikimedia.org" style={link}>Wikimedia Commons</a>, used under the license named below.
            Players with neither get a silhouette. Each photo may be cropped to fit the game.
          </p>
          <ul style={{ display: "flex", flexDirection: "column", gap: "0.35rem", fontSize: "0.92rem" }}>
            {rows.map((c) => (
              <li key={c.file}>
                <strong>{c.player}</strong>
                {" — "}
                <a href={`https://commons.wikimedia.org/wiki/File:${encodeURIComponent(c.file)}`} style={link}>photo</a>
                {` by ${c.artist}, `}
                {c.license_url ? <a href={c.license_url} style={link}>{c.license}</a> : c.license}
              </li>
            ))}
          </ul>
        </article>
      </main>
    </>
  );
}
